<?php declare(strict_types=1); namespace App\Http\Resources\Admin; use Illuminate\Http\Resources\Json\JsonResource; /** @mixin \App\Models\WorkflowTaskDefinition */ final class WorkflowTaskDefinitionResource extends JsonResource { public function toArray($r): array { return ['id'=>$this->id,'code'=>$this->code,'title_en'=>$this->title_en,'title_ar'=>$this->title_ar,'instructions_en'=>$this->instructions_en,'instructions_ar'=>$this->instructions_ar,'department'=>$this->whenLoaded('department',fn()=>['id'=>$this->department->id,'code'=>$this->department->code,'name'=>$this->department->name_en]),'sla_minutes'=>$this->sla_minutes,'escalate_after_minutes'=>$this->escalate_after_minutes,'priority'=>$this->priority?->value,'is_entry_point'=>$this->is_entry_point]; }}